// ---------------------------------------------------------------------------------------
// Jobs+ helpers
// ---------------------------------------------------------------------------------------
const JOB_NAMES = {
  alchemist: 'Alchemist', cook: 'Cook', enchanter: 'Enchanter', explorer: 'Explorer', farmer: 'Farmer',
  hunter: 'Hunter', jeweler: 'Jeweler', miner: 'Miner', smith: 'Smith',
}

// The player's Job object for a job id like 'smith', or null if they don't have that job.
function jobOf(player, job) {
  const instance = $JobInstance.of($ResourceLocation.parse('jobsplus:' + job))
  if (instance == null) return null
  return player.jobsplus$getJob(instance)
}

// The highest tier (1-3) of a power-up family ('second_helping' -> second_helping_i/ii/iii) the player has
// bought and switched on in the Jobs menu, or 0.
const $PowerupInstance = Java.loadClass('com.daqem.jobsplus.integration.arc.holder.holders.powerup.PowerupInstance')
function powerupTier(player, job, family) {
  const j = jobOf(player, job)
  if (j == null) return 0
  const manager = j.getPowerupManager()
  const numerals = ['iii', 'ii', 'i']
  for (let i = 0; i < numerals.length; i++) {
    var inst = $PowerupInstance.of($ResourceLocation.parse(`jobsplus:${job}/${family}_${numerals[i]}`))
    if (inst == null) continue
    var owned = manager.getPowerup(inst)
    if (owned.isPresent() && String(owned.get().getState()) == 'ACTIVE') return 3 - i
  }
  return 0
}

function jobLevel(player, job) {
  const j = jobOf(player, job)
  return j == null ? 0 : j.getLevel()
}

// Adds job XP (Jobs+ applies its global XP multiplier and handles level-ups and coins).
// Shows a short action-bar note so players see where the XP came from.
function giveJobXp(player, job, amount, why) {
  const j = jobOf(player, job)
  if (j == null || amount <= 0) return false
  j.addExperience(amount)
  if (why) player.setStatusMessage(Text.of(`+${Math.round(amount)} ${JOB_NAMES[job]} XP: ${why}`).gold())
  return true
}

function itemId(stack) {
  return String($BuiltInRegistries.ITEM.getKey(stack.getItem()))
}

// ---------------------------------------------------------------------------------------
// /minerpg_jobs (operators and quest rewards; quest command rewards run at permission 2)
//   /minerpg_jobs coins <players> <amount>        give Gold Coins (the money, see minerpg_coins.js)
//   /minerpg_jobs xp <players> <job> <amount>     add job XP (only if they have the job)
//   /minerpg_jobs grant <players> <advancement>   grant an advancement without chat feedback
// ---------------------------------------------------------------------------------------
// Survey Map recipes (the three higher maps are gated by Explorer level in the minerpg_jobs datapack).
ServerEvents.recipes(event => {
  event.shapeless('minerpg:survey_map_settlement', ['minecraft:map', 'minecraft:emerald']).id('minerpg:survey_map_settlement')
  event.shapeless('minerpg:survey_map_crypt', ['minecraft:map', 'minecraft:bone', 'minecraft:emerald']).id('minerpg:survey_map_crypt')
  event.shapeless('minerpg:survey_map_dungeon', ['minecraft:map', 'minecraft:gold_ingot', 'minecraft:ender_pearl']).id('minerpg:survey_map_dungeon')
  event.shapeless('minerpg:survey_map_lair', ['minecraft:map', 'minecraft:diamond', 'minecraft:gold_ingot', 'minecraft:ender_pearl']).id('minerpg:survey_map_lair')
})

ServerEvents.commandRegistry(event => {
  const { commands: Commands, arguments: Arguments } = event
  event.register(Commands.literal('minerpg_jobs')
    .requires(source => source.hasPermission(2))
    .then(Commands.literal('coins')
      .then(Commands.argument('players', Arguments.PLAYERS.create(event))
        .then(Commands.argument('amount', Arguments.INTEGER.create(event))
          .executes(ctx => {
            const amount = Arguments.INTEGER.getResult(ctx, 'amount')
            let n = 0
            Arguments.PLAYERS.getResult(ctx, 'players').forEach(p => {
              giveCoins(p, amount * COPPER_PER_GOLD)
              p.tell(Text.of(`+${amount} Gold Coins`).gold())
              n++
            })
            return n
          }))))
    .then(Commands.literal('xp')
      .then(Commands.argument('players', Arguments.PLAYERS.create(event))
        .then(Commands.argument('job', Arguments.WORD.create(event))
          .then(Commands.argument('amount', Arguments.INTEGER.create(event))
            .executes(ctx => {
              const job = String(Arguments.WORD.getResult(ctx, 'job'))
              const amount = Arguments.INTEGER.getResult(ctx, 'amount')
              let n = 0
              Arguments.PLAYERS.getResult(ctx, 'players').forEach(p => { if (giveJobXp(p, job, amount, 'reward')) n++ })
              return n
            })))))
    .then(Commands.literal('grant')
      .then(Commands.argument('players', Arguments.PLAYERS.create(event))
        .then(Commands.argument('advancement', Arguments.RESOURCE_LOCATION.create(event))
          .executes(ctx => {
            const id = Arguments.RESOURCE_LOCATION.getResult(ctx, 'advancement')
            let n = 0
            Arguments.PLAYERS.getResult(ctx, 'players').forEach(p => {
              if (!p.isAdvancementDone(id)) { p.unlockAdvancement(id); n++ }
            })
            return n
          })))))

  // /leavejob <job>: warns what the player loses; /leavejob <job> confirm (within a minute) takes LEAVE_JOB_PRICE
  // gold and drops the job, its level and its power-ups for good, freeing the slot for another (designer,
  // 2026-10-31: two jobs at most; 2026-11-01: leaving costs gold).
  let leave = Commands.literal('leavejob').requires(source => source.isPlayer())
  Object.keys(JOB_NAMES).forEach(key => {
    leave = leave.then(Commands.literal(key)
      .executes(ctx => leaveJobWarn(ctx.source.player, key))
      .then(Commands.literal('confirm').executes(ctx => leaveJobConfirm(ctx.source.player, key))))
  })
  event.register(leave)
})

// Player UUID -> {job, time} of the last /leavejob warning, so "confirm" only works right after it.
const LEAVE_JOB_PENDING = {}
const LEAVE_JOB_WINDOW_MS = 60000
const LEAVE_JOB_PRICE = 5 // Gold Coins

function leaveJobWarn(player, key) {
  const job = jobOf(player, key)
  if (job == null) {
    player.tell(Text.of(`You don't have the ${JOB_NAMES[key]} job.`).red())
    return 0
  }
  LEAVE_JOB_PENDING[String(player.getGameProfile().getId())] = { job: key, time: Date.now() }
  player.tell(Text.of(`Leaving the ${JOB_NAMES[key]} job costs ${LEAVE_JOB_PRICE} gold and deletes it for good: `
    + `level ${job.getLevel()}, its XP and every power-up bought for it. You can then join another job.`).gold())
  player.tell(Text.of(`[Leave ${JOB_NAMES[key]}]`).red().bold()
    .clickRunCommand(`/leavejob ${key} confirm`)
    .hover(Text.of(`Click to leave the ${JOB_NAMES[key]} job (within a minute)`))
    .append(Text.of('  or type ').white().bold(false))
    .append(Text.of(`/leavejob ${key} confirm`).yellow().bold(false)))
  return 1
}

function leaveJobConfirm(player, key) {
  const pending = LEAVE_JOB_PENDING[String(player.getGameProfile().getId())]
  if (!pending || pending.job != key || Date.now() - pending.time > LEAVE_JOB_WINDOW_MS) {
    player.tell(Text.of(`Type /leavejob ${key} first to see what you would lose.`).red())
    return 0
  }
  delete LEAVE_JOB_PENDING[String(player.getGameProfile().getId())]
  if (jobOf(player, key) == null) {
    player.tell(Text.of(`You don't have the ${JOB_NAMES[key]} job.`).red())
    return 0
  }
  if (coinWallet(player) < LEAVE_JOB_PRICE * COPPER_PER_GOLD) {
    player.tell(Text.of(`Leaving a job costs ${LEAVE_JOB_PRICE} gold, and you carry less.`).red())
    return 0
  }
  takeCoins(player, LEAVE_JOB_PRICE * COPPER_PER_GOLD)
  syncCoinBalance(player)
  player.jobsplus$removeJob($JobInstance.of($ResourceLocation.parse('jobsplus:' + key)))
  player.tell(Text.of(`You left the ${JOB_NAMES[key]} job. Press J to join another.`).green())
  console.info(`[minerpg] ${player.username} left the ${key} job`)
  return 1
}

// ---------------------------------------------------------------------------------------
// Spell binding, spell books, gem sockets: repeatable hidden advancements. Give the XP, then
// revoke the advancement next tick so the next bind/socket fires it again.
// ---------------------------------------------------------------------------------------
// (KubeJS's PlayerEvents.advancement and NeoForge's "earned" event only fire for advancements
// with a display, so this listens to NeoForge's per-criterion progress event instead.)
const $AdvancementProgressEvent = Java.loadClass('net.neoforged.neoforge.event.entity.player.AdvancementEvent$AdvancementProgressEvent')
NativeEvents.onEvent($AdvancementProgressEvent, event => {
  if (String(event.getProgressType()) != 'GRANT') return
  const id = String(event.getAdvancement().id())
  const entry = ADVANCEMENT_XP[id]
  if (!entry || !event.getAdvancementProgress().isDone()) return
  const player = event.getEntity()
  giveJobXp(player, entry[0], entry[1], entry[2])
  player.server.scheduleInTicks(1, () => player.revokeAdvancement(id))
})

// ---------------------------------------------------------------------------------------
// Workstation watchers: reforging, salvaging, gem cutting, cooking pot, keg.
// None of these fire an event, so while a player has one open we compare its slots (and the
// player's "items crafted" statistic) from one tick to the next.
// ---------------------------------------------------------------------------------------
const watch = {} // player uuid -> { menuId, ...last tick's numbers }

function slotCount(menu, index) {
  return menu.getSlot(index).getItem().getCount()
}

// Throttled action-bar warning (once every 2 seconds per player).
function warn(player, state, text) {
  const now = player.server.getTickCount()
  if (state.warnedAt && now - state.warnedAt < 40) return
  state.warnedAt = now
  player.setStatusMessage(Text.of(text).red())
  player.tell(Text.of(text).red())
}

// Reforging table: slot 0 = item, 1 = rarity material, 2 = gem dust, 3-5 = the three offers.
// A reforge uses up material and experience in the same tick (taking an offer charges both).
// Experience is read as level + progress (the "total experience" counter isn't kept in sync by
// every source of levels).
function reforgeTick(player, menu, state) {
  const material = menu.getSlot(1).getItem()
  const rarity = material.isEmpty() ? null : RARITY_BY_MATERIAL[itemId(material)]
  if (rarity && jobLevel(player, 'smith') < REFORGE_LEVEL[rarity]) {
    // Gate: hand the material back; with no material the table offers nothing.
    const back = material.copy()
    menu.getSlot(1).set($ItemStack.EMPTY)
    player.getInventory().placeItemBackInInventory(back)
    warn(player, state, `Reforging to ${rarity} needs Smith level ${REFORGE_LEVEL[rarity]} (Jobs: J). ${rarity} gear still drops from bosses and dungeons.`)
  }
  const matCount = material.getCount()
  const xp = player.experienceLevel + player.experienceProgress
  if (state.rarity && state.matCount > matCount && xp < state.xp) {
    giveJobXp(player, 'smith', REFORGE_XP[state.rarity], `reforged (${state.rarity})`)
  }
  state.rarity = material.isEmpty() ? state.rarity : rarity
  state.matCount = matCount
  state.xp = xp
}

// Salvaging table: slots 0-11 = items to salvage, 12-17 = salvaged materials. Pressing the
// button empties the inputs and fills the outputs in the same tick.
function salvageTick(player, menu, state) {
  let inputs = 0
  let outputs = 0
  for (let i = 0; i < 12; i++) if (!menu.getSlot(i).getItem().isEmpty()) inputs++
  for (let i = 12; i < 18; i++) outputs += slotCount(menu, i)
  if (state.inputs != null && inputs < state.inputs && outputs > state.outputs) {
    const n = state.inputs - inputs
    giveJobXp(player, 'smith', SALVAGE_XP * n, `salvaged ${n} item${n > 1 ? 's' : ''}`)
  }
  state.inputs = inputs
  state.outputs = outputs
}

// Apotheosis Gem Cutting Table: slot 0 = the gem being raised, 1-3 = the second gem, gem dust and
// the purity material. A cut uses up slots 1-3 and replaces the gem in slot 0 with the next purity in
// the same tick, so: inputs went down while slot 0 held a gem before and after, now a different one.
function apoCutTick(player, menu, state) {
  const base = menu.getSlot(0).getItem().copy()
  let inputs = 0
  for (let i = 1; i < 4; i++) inputs += slotCount(menu, i)
  if (state.base != null && !state.base.isEmpty() && !base.isEmpty() && inputs < state.inputs
      && !$ItemStack.isSameItemSameComponents(base, state.base)) {
    giveJobXp(player, 'jeweler', GEM_UPGRADE_XP, 'gem purity raised')
  }
  state.base = base
  state.inputs = inputs
}

// Gem cutting (Jewelry) and the cooking pot: count how many of the result (same item, same
// cut/components) the player holds, in the inventory or on the cursor. When that number goes up
// while the station is open, the player took results out of it. (Neither station fires an event,
// and taking a result doesn't reliably update the "items crafted" statistic.)
function holding(player, menu, sample) {
  let n = 0
  const inv = player.getInventory()
  // (No const/let inside the loop body: Rhino keeps the first value of a block-scoped const.)
  for (let i = 0; i < inv.getContainerSize(); i++) n += countIfSame(inv.getItem(i), sample)
  return n + countIfSame(menu.getCarried(), sample)
}

function countIfSame(stack, sample) {
  return !stack.isEmpty() && $ItemStack.isSameItemSameComponents(stack, sample) ? stack.getCount() : 0
}

function craftedTick(player, menu, state, outputSlot, job, xpEach, what, extraChance, onMade) {
  if (state.sample != null) {
    const made = holding(player, menu, state.sample) - state.have
    if (made > 0) {
      giveJobXp(player, job, xpEach * made, `${made} ${what}`)
      if (onMade) onMade(state.sample)
      // Extra servings go straight to the inventory, after the count is read, so they aren't counted as made.
      let extra = 0
      for (let i = 0; i < made; i++) if (extraChance > 0 && player.getRandom().nextFloat() < extraChance) extra++
      if (extra > 0) {
        player.getInventory().placeItemBackInInventory(state.sample.copyWithCount(extra))
        player.tell(Text.of(`Second Helping: +${extra} serving${extra > 1 ? 's' : ''}`).gold())
      }
    }
  }
  const out = menu.getSlot(outputSlot).getItem()
  if (!out.isEmpty()) state.sample = out.copyWithCount(1)
  state.have = state.sample == null ? 0 : holding(player, menu, state.sample)
}

PlayerEvents.tick(event => {
  const player = event.player
  const menu = player.containerMenu
  const key = String(player.getGameProfile().getId())
  let kind = null
  if (menu instanceof $ReforgingMenu) kind = 'reforge'
  else if (menu instanceof $SalvagingMenu) kind = 'salvage'
  else if (menu instanceof $GemCuttingMenu) kind = 'gem'
  else if (menu instanceof $ApoGemCuttingMenu) kind = 'apo_gem'
  else if (menu instanceof $CookingPotMenu) kind = 'pot'
  else if (menu instanceof $KegMenu) kind = 'keg'
  else if (menu instanceof $OssuaryMenu) kind = 'ossuary'
  else if (menu instanceof $WeaponFusionMenu) kind = 'fusion'
  if (kind == null) {
    if (watch[key]) delete watch[key]
    return
  }
  let state = watch[key]
  // (Compare the window id: Rhino wraps the same Java menu in a new object every tick.)
  if (!state || state.menuId != menu.containerId) {
    state = { menuId: menu.containerId }
    watch[key] = state
  }
  try {
    if (kind == 'reforge') reforgeTick(player, menu, state)
    else if (kind == 'salvage') salvageTick(player, menu, state)
    else if (kind == 'gem') craftedTick(player, menu, state, 1, 'jeweler', GEM_CUT_XP, 'gem(s) cut', 0)
    else if (kind == 'apo_gem') apoCutTick(player, menu, state)
    else if (kind == 'ossuary') craftedTick(player, menu, state, 1, 'smith', OSSUARY_XP, 'carved', 0)
    else if (kind == 'fusion') craftedTick(player, menu, state, 2, 'smith', FUSION_XP, 'weapon(s) fused', 0)
    else if (kind == 'keg') craftedTick(player, menu, state, KEG_OUTPUT_SLOT, 'cook', KEG_XP, 'drink(s) poured', 0,
      drink => firstDish(player, drink))
    else {
      var tier = powerupTier(player, 'cook', 'second_helping')
      craftedTick(player, menu, state, 8, 'cook', MEAL_XP, 'meal(s) cooked', tier > 0 ? SECOND_HELPING_CHANCE[tier - 1] : 0,
        meal => firstDish(player, meal))
    }
  } catch (e) {
    console.error(`[minerpg] jobs watcher (${kind}) failed: ${e}`)
    delete watch[key]
  }
})

PlayerEvents.loggedOut(event => { delete watch[String(event.player.getGameProfile().getId())] })

// The anvil (taking the result fires NeoForge's AnvilRepairEvent): armor + Socket Mount fixes a socket and
// armor + cut gem sets the gem (Jeweler); anything + enchanted book is enchanting (Enchanter).
NativeEvents.onEvent($AnvilRepairEvent, event => {
  try {
    var right = event.getRight()
    if (right.isEmpty()) return
    if (itemId(right) == 'jewelry:socket_mount') giveJobXp(event.getEntity(), 'jeweler', MOUNT_XP, 'socket mounted')
    // ItemStack.is is overloaded (Item, HolderSet, TagKey) and Rhino can't pick one for a TagKey: name the overload.
    else if (right['is(net.minecraft.tags.TagKey)'](JEWELRY_GEMS)) giveJobXp(event.getEntity(), 'jeweler', SET_GEM_XP, 'gem set')
    else if (itemId(right) == 'minecraft:enchanted_book') {
      var stored = right.get($DataComponents.STORED_ENCHANTMENTS)
      var levels = 0
      if (stored != null) {
        var entries = stored.entrySet().iterator()
        while (entries.hasNext()) levels += entries.next().getIntValue()
      }
      giveJobXp(event.getEntity(), 'enchanter', ANVIL_BOOK_XP_PER_LEVEL * levels, 'enchanted at the anvil')
    }
  } catch (e) {
    console.error(`[minerpg] jobs anvil socketing failed: ${e}`)
  }
})

// ---------------------------------------------------------------------------------------
// Cook: a bonus the first time each dish is made (remembered per player by item id), XP for pot meals served by
// right-clicking the pot with a bowl, and for raw food put on a campfire, stove or skillet. Both clicks are read one
// tick later: the held stack shrank only if the pot served a meal or the fire took the food.
// ---------------------------------------------------------------------------------------
function firstDish(player, stack) {
  if (jobOf(player, 'cook') == null) return
  const id = itemId(stack)
  const data = player.persistentData
  const dishes = data.getCompound('minerpg_dishes')
  if (dishes.contains(id)) return
  dishes.putBoolean(id, true)
  data.put('minerpg_dishes', dishes)
  giveJobXp(player, 'cook', FIRST_DISH_XP, 'new dish, ' + stack.getHoverName().getString())
}

BlockEvents.rightClicked(event => {
  const player = event.player
  if (player == null || String(event.hand) != 'MAIN_HAND' || jobOf(player, 'cook') == null) return
  const blockId = String(event.block.id)
  const pot = blockId == 'farmersdelight:cooking_pot'
  if (!pot && COOK_FIRE_BLOCKS.indexOf(blockId) < 0) return
  const held = player.getMainHandItem()
  if (held.isEmpty()) return
  const heldId = itemId(held)
  const before = held.getCount()
  // (Only food on a fire, only the pot's serving container on a pot: a block placed beside them also shrinks the stack.)
  if (!pot && !held.has($DataComponents.FOOD)) return
  const meal = pot ? event.block.entity.getMeal().copy() : null
  if (pot && (meal.isEmpty() || itemId(event.block.entity.getContainer()) != heldId)) return
  player.server.scheduleInTicks(1, () => {
    try {
      var now = player.getMainHandItem()
      var used = before - (itemId(now) == heldId ? now.getCount() : 0)
      if (used <= 0) return
      if (pot) {
        giveJobXp(player, 'cook', MEAL_XP * used, `${used} meal(s) served`)
        firstDish(player, meal)
      } else {
        giveJobXp(player, 'cook', COOK_FIRE_XP * used, 'food on the fire')
      }
    } catch (e) {
      console.error(`[minerpg] cook click failed: ${e}`)
    }
  })
})

// Cook: a cutting board cut (pack 1.5.5). Clicking the board with a tool cuts what lies on it; read a tick later
// whether it is gone (a click with nothing that cuts it, or an empty hand taking it back, pays nothing).
BlockEvents.rightClicked(event => {
  const player = event.player
  if (player == null || String(event.hand) != 'MAIN_HAND' || String(event.block.id) != 'farmersdelight:cutting_board') return
  if (jobOf(player, 'cook') == null || player.getMainHandItem().isEmpty()) return
  const board = event.block.entity
  if (board == null || board.getStoredItem().isEmpty()) return
  player.server.scheduleInTicks(1, () => {
    try {
      if (board.getStoredItem().isEmpty()) giveJobXp(player, 'cook', CUTTING_XP, 'cut on the board')
    } catch (e) {
      console.error(`[minerpg] cutting board XP failed: ${e}`)
    }
  })
})

// Hunter: a creature caught in Naturalist's capture net (pack 1.5.5): the net turns it into an item, so it is gone a
// tick later.
ItemEvents.entityInteracted(event => {
  const player = event.player
  if (player == null || itemId(event.item) != 'naturalist:capture_net' || jobOf(player, 'hunter') == null) return
  const target = event.target
  player.server.scheduleInTicks(1, () => {
    try {
      if (target.isRemoved()) giveJobXp(player, 'hunter', NET_XP, 'caught in the net')
    } catch (e) {
      console.error(`[minerpg] bug net XP failed: ${e}`)
    }
  })
})

// ---------------------------------------------------------------------------------------
// "Extra copy" power-ups for crafting-table results: Second Helping (Cook meals and feasts), Mapmaker
// (Survey Maps), Waywright (scrolls, Warp Stones, waystones, Sharestones, Portstones, Warp Plates).
// ---------------------------------------------------------------------------------------
ItemEvents.crafted(event => {
  try {
    var player = event.player
    var result = event.item
    if (player == null || result.isEmpty()) return
    if (result.hasTag('minerpg:job_bonus/second_helping')) firstDish(player, result)
    // Explorer: XP for a newly made atlas only. Adding maps to an atlas (or cutting one) also crafts an atlas, with
    // the atlas itself in the grid (pack 1.5.1: adding maps one at a time was an XP farm).
    if (result.id == 'map_atlases:atlas' && jobOf(player, 'explorer') != null) {
      var grid = event.inventory, hadAtlas = false
      for (var i = 0; i < grid.getContainerSize(); i++) if (grid.getItem(i).id == 'map_atlases:atlas') hadAtlas = true
      if (!hadAtlas) giveJobXp(player, 'explorer', ATLAS_XP[0] + player.getRandom().nextInt(ATLAS_XP[1] - ATLAS_XP[0] + 1), 'atlas made')
    }
    EXTRA_COPY.forEach(([job, family, tag, chances]) => {
      if (!result.hasTag(tag)) return
      var tier = powerupTier(player, job, family)
      if (tier > 0 && player.getRandom().nextFloat() < chances[tier - 1]) {
        player.getInventory().placeItemBackInInventory(result.copy())
        player.tell(Text.of(`${family == 'second_helping' ? 'Second Helping' : family == 'mapmaker' ? 'Mapmaker' : 'Waywright'}: one more ${result.getHoverName().getString()}`).gold())
      }
    })
  } catch (e) {
    console.error(`[minerpg] jobs extra copy failed: ${e}`)
  }
})

// ---------------------------------------------------------------------------------------
// Survey Maps (Explorer): using one runs its loot table (an explorer map to the nearest place of that kind,
// searched from the player). If nothing is in range the loot table hands back a blank map: take that away
// and give the Survey Map back.
// ---------------------------------------------------------------------------------------
function countItem(player, id) {
  let n = 0
  const inv = player.getInventory()
  for (let i = 0; i < inv.getContainerSize(); i++) {
    var stack = inv.getItem(i)
    if (!stack.isEmpty() && itemId(stack) == id) n += stack.getCount()
  }
  return n
}

ItemEvents.rightClicked(event => {
  const stack = event.item
  const id = itemId(stack)
  const table = SURVEY_MAPS[id]
  if (!table) return
  // event.cancel() ends this handler on the spot (KubeJS 7), so it comes last in each branch: called first, as it
  // was until pack 1.5.4, nothing below it ever ran and the maps did nothing.
  const player = event.player
  if (player.level.isClientSide()) return
  if (String(player.level.dimension) != 'minecraft:overworld') {
    player.setStatusMessage(Text.of('Survey Maps only chart the Overworld.').red())
    event.cancel()
  }
  const name = player.getGameProfile().getName()
  const blanks = countItem(player, 'minecraft:map')
  stack.shrink(1)
  player.server.runCommandSilent(`execute as ${name} at @s run loot give @s loot ${table}`)
  if (countItem(player, 'minecraft:map') > blanks) {
    player.server.runCommandSilent(`clear ${name} minecraft:map 1`)
    player.getInventory().placeItemBackInInventory(Item.of(id))
    player.setStatusMessage(Text.of('Nothing of that kind lies within reach of this map. Try again farther out.').red())
  } else {
    player.setStatusMessage(Text.of('The map fills in. Copy it at a cartography table to share it.').gold())
  }
  event.cancel()
})

// ---------------------------------------------------------------------------------------
// Explorer: XP the first time they use each waystone (remembered per player, by position).
// ---------------------------------------------------------------------------------------
BlockEvents.rightClicked(event => {
  const block = event.block
  if (!block.hasTag('waystones:waystones')) return
  const player = event.player
  if (player == null || jobOf(player, 'explorer') == null) return
  // A waystone is two blocks tall: key it by its lower half.
  const lower = block.down.hasTag('waystones:waystones') ? block.down : block
  const key = `${block.level.dimension}|${lower.x}|${lower.y}|${lower.z}`
  const data = player.persistentData
  const seen = String(data.getString('minerpg_waystones') || '')
  if (seen.split(';').indexOf(key) >= 0) return
  data.putString('minerpg_waystones', seen ? seen + ';' + key : key)
  giveJobXp(player, 'explorer', WAYSTONE_XP, 'new waystone')
})

// ---------------------------------------------------------------------------------------
// Explorer discovery: XP the first time an Explorer enters each biome and walks into each structure (remembered
// per player: biomes by id, structures by kind and start chunk), and for each map they fill in. A map pays once
// for the whole server (by map id, so copies and locked maps don't pay again); a zoomed-out map is a new map.
// ---------------------------------------------------------------------------------------
function discover(player, kind, key, xp, why) {
  const data = player.persistentData
  const seen = data.getCompound('minerpg_explored_' + kind)
  if (seen.contains(key)) return
  seen.putBoolean(key, true)
  data.put('minerpg_explored_' + kind, seen)
  giveJobXp(player, 'explorer', xp, why)
}

function prettyId(id) {
  const path = id.substring(id.indexOf(':') + 1)
  return path.split('/').pop().split('_').map(w => w.charAt(0).toUpperCase() + w.substring(1)).join(' ')
}

function discoveryTick(player) {
  const level = player.level
  const pos = player.blockPosition()
  const dim = String(level.dimension)

  const biome = level.getBiome(pos).unwrapKey()
  if (biome.isPresent()) {
    var biomeId = String(biome.get().location())
    discover(player, 'biomes', biomeId, BIOME_XP, 'new biome, ' + prettyId(biomeId))
  }

  const structures = level.structureManager()
  if (structures.hasAnyStructureAt(pos)) {
    var registry = level.registryAccess().registryOrThrow($Registries.STRUCTURE)
    var found = structures.getAllStructuresAt(pos).keySet().iterator()
    while (found.hasNext()) {
      var structure = found.next()
      var start = structures.getStructureAt(pos, structure)
      if (!start.isValid() || !structures.structureHasPieceAt(pos, start)) continue
      var structureId = String(registry.getKey(structure))
      var chunk = start.getChunkPos()
      discover(player, 'structures', `${dim}|${structureId}|${chunk.x}|${chunk.z}`, STRUCTURE_XP,
        'discovered ' + prettyId(structureId))
    }
  }

  const held = player.getMainHandItem()
  if (held.id == 'minecraft:filled_map') {
    var mapId = held.get($DataComponents.MAP_ID)
    // (level.getMapData, not MapItem.getSavedData: Rhino can't pick between that method's two overloads.)
    var map = mapId == null ? null : level.getMapData(mapId)
    if (map != null) {
      var mapsDone = player.server.persistentData.getCompound('minerpg_maps_completed')
      var mapKey = String(mapId.id())
      if (!mapsDone.contains(mapKey)) {
        var colors = map.colors
        var filled = 0
        for (var i = 0; i < colors.length; i++) if (colors[i] != 0) filled++
        if (filled >= colors.length * MAP_COMPLETE_SHARE) {
          mapsDone.putBoolean(mapKey, true)
          player.server.persistentData.put('minerpg_maps_completed', mapsDone)
          giveJobXp(player, 'explorer', MAP_COMPLETE_XP * Math.pow(2, map.scale), 'map completed')
        }
      }
    }
  }
}

PlayerEvents.tick(event => {
  const player = event.player
  if (player.tickCount % DISCOVERY_TICKS != 0) return
  if (jobOf(player, 'explorer') == null) return
  try {
    discoveryTick(player)
  } catch (e) {
    console.error(`[minerpg] explorer discovery failed for ${player.username}: ${e}`)
  }
})

// ---------------------------------------------------------------------------------------
// Hunter = Skinning (designer revision). Plain kills give no Hunter XP (the Jobs+ "kill any mob"
// action is replaced by an animals-only one in the minerpg_jobs datapack). Instead, when a
// Hunter kills a creature, every hide, bone or monster part it drops gives Hunter XP, and the
// Hunter's level adds skinning yield: a chance of one extra of each material, and rare parts
// once the Hunter is skilled enough.
// ---------------------------------------------------------------------------------------
EntityEvents.drops(event => {
  const killer = event.source.player
  if (killer == null) return
  if (jobOf(killer, 'hunter') == null) return // not a Hunter: normal drops, no XP
  const level = jobLevel(killer, 'hunter')
  const entity = event.entity
  const entityId = String(entity.getEncodeId())
  const random = killer.getRandom()
  const extraChance = Math.min(SKIN_EXTRA_MAX, level * SKIN_EXTRA_PER_LEVEL)
  let xp = 0
  let extra = []
  event.drops.forEach(drop => {
    const stack = drop.getItem()
    const value = SKIN_XP[itemId(stack)]
    if (!value) return
    xp += value * stack.getCount()
    if (random.nextFloat() < extraChance) extra.push(stack.copyWithCount(1))
  })
  SKIN_RARE.forEach(([type, item, needed, chance]) => {
    if (type == entityId && level >= needed && random.nextFloat() < chance) extra.push(Item.of(item))
  })
  extra.forEach(stack => {
    event.addDrop(stack)
    xp += SKIN_XP[itemId(stack)] || 0
  })
  if (xp > 0) giveJobXp(killer, 'hunter', xp, extra.length > 0 ? `skinned (+${extra.length} extra)` : 'skinned')
})

// ---------------------------------------------------------------------------------------
// Class merchants buy job-made goods.
// ---------------------------------------------------------------------------------------
function professionId(villager) {
  return String($BuiltInRegistries.VILLAGER_PROFESSION.getKey(villager.getVillagerData().getProfession()))
}

ItemEvents.entityInteracted(event => {
  const target = event.target
  if (!(target instanceof $Villager)) return
  const buys = MERCHANT_BUYS[professionId(target)]
  if (!buys) return
  const offers = target.getOffers()
  buys.forEach(([id, count, emeralds]) => {
    const item = $BuiltInRegistries.ITEM.get($ResourceLocation.parse(id))
    let present = false
    offers.forEach(o => {
      if (o.getItemCostA().item().value() == item && itemId(o.getResult()) == 'minecraft:emerald') present = true
    })
    if (!present) {
      offers.add(new $MerchantOffer(new $ItemCost(item, count), $Optional.empty(),
        Item.of('minecraft:emerald', emeralds), MERCHANT_MAX_USES, MERCHANT_VILLAGER_XP, 0.05))
    }
  })
})
